// Skills.jsx
import { useEffect, useRef, useState } from 'react';
import './styles.css';

// Logos live in  public/logos/  (copy the "logos" folder there).
const logo = (file) => `${process.env.PUBLIC_URL || ''}/logos/${file}.svg`;

const ROW_ONE = [
  { name: 'React',        icon: logo('react') },
  { name: 'HTML5',        icon: logo('html5') },
  { name: 'CSS3',         icon: logo('css3') },
  { name: 'JavaScript',   icon: logo('javascript') },
  { name: 'Tailwind CSS', icon: logo('tailwindcss') },
  { name: 'Figma',        icon: logo('figma') },
  { name: 'Git',          icon: logo('git') },
  { name: 'GitHub',       icon: logo('github') },
  { name: 'Arduino',       icon: logo('arduino') },
  { name: 'Linux',       icon: logo('linux') },
];

const ROW_TWO = [
  { name: 'Node.js',    icon: logo('nodejs') },
  { name: 'Express.js', icon: logo('express') },
  { name: 'MongoDB',    icon: logo('mongodb') },
  { name: 'Python',     icon: logo('python') },
  { name: 'Java',       icon: logo('java') },
  { name: 'Cisco',      icon: logo('cisco') },
  { name: 'Postman',    icon: logo('postman') },
  { name: 'VS Code',    icon: logo('vscode') },
  { name: 'Postgre sql',    icon: logo('postgresql') },
  { name: 'Wamp',    icon: logo('wamp') },
  { name: 'Xampp',    icon: logo('xampp') },
  { name: 'Supabase',    icon: logo('supabase') },
];

function SkillTile({ skill, lit, onToggle, hidden }) {
  return (
    <button
      type="button"
      className={`skill-tile ${lit ? 'is-lit' : ''}`}
      onClick={() => onToggle(skill.name)}
      aria-pressed={lit}
      aria-label={skill.name}
      tabIndex={hidden ? -1 : 0}
    >
      <span className="skill-logo-wrap">
        <img
          className="skill-logo"
          src={skill.icon}
          alt=""
          draggable="false"
          onError={(e) => {
            e.currentTarget.style.display = 'none';
            e.currentTarget.parentElement.dataset.fallback = skill.name[0];
          }}
        />
      </span>
      <span className="skill-tile-name">{skill.name}</span>
    </button>
  );
}

/* A row that scrolls left → right by itself, and that you can also
   drag, swipe or wheel-scroll. Auto-scroll pauses while you hover,
   touch or drag, and picks up again afterwards. */
function MarqueeRow({ items, speed, lit, onToggle }) {
  const rowRef = useRef(null);
  const pausedRef = useRef(false);   // hover / touch / drag
  const resumeTimer = useRef(null);
  const drag = useRef({ active: false, startX: 0, startLeft: 0, moved: false });

  useEffect(() => {
    const row = rowRef.current;
    if (!row) return;
    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    // Width of one full group (the track holds two identical groups)
    const groupWidth = () => row.firstElementChild.firstElementChild.offsetWidth;

    // Keep scrollLeft inside one group so the loop never shows an edge
    const wrap = () => {
      const g = groupWidth();
      if (!g) return;
      if (row.scrollLeft < 1) row.scrollLeft += g;
      else if (row.scrollLeft >= g) row.scrollLeft -= g;
    };

    row.scrollLeft = groupWidth() - 1; // start at the right end so we can move right

    let raf;
    let last;
    const tick = (now) => {
      if (last === undefined) last = now;
      const dt = Math.min(now - last, 64) / 1000;
      last = now;
      if (!pausedRef.current && !reduce) {
        row.scrollLeft -= speed * dt; // decreasing scrollLeft = content moves right
      }
      wrap();
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);

    const onResize = () => wrap();
    window.addEventListener('resize', onResize);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener('resize', onResize);
      clearTimeout(resumeTimer.current);
    };
  }, [speed]);

  const pause = () => {
    clearTimeout(resumeTimer.current);
    pausedRef.current = true;
  };
  const resumeSoon = (ms = 1500) => {
    clearTimeout(resumeTimer.current);
    resumeTimer.current = setTimeout(() => (pausedRef.current = false), ms);
  };

  // Mouse: hover pauses, drag scrolls
  const onPointerEnter = (e) => e.pointerType === 'mouse' && pause();
  const onPointerLeave = (e) => {
    if (e.pointerType === 'mouse' && !drag.current.active) resumeSoon(300);
  };
  const onPointerDown = (e) => {
    if (e.pointerType !== 'mouse' || e.button !== 0) return;
    drag.current = { active: true, startX: e.clientX, startLeft: rowRef.current.scrollLeft, moved: false };
    pause();
  };
  const onPointerMove = (e) => {
    const d = drag.current;
    if (!d.active) return;
    const dx = e.clientX - d.startX;
    if (Math.abs(dx) > 5) d.moved = true;
    rowRef.current.scrollLeft = d.startLeft - dx;
  };
  const endDrag = () => {
    if (!drag.current.active) return;
    drag.current.active = false;
    rowRef.current.classList.remove('is-dragging');
  };
  // A drag shouldn't count as a click on the logo underneath
  const onClickCapture = (e) => {
    if (drag.current.moved) {
      e.stopPropagation();
      e.preventDefault();
      drag.current.moved = false;
    }
  };

  
  const onTouchStart = () => pause();
  const onTouchEnd = () => resumeSoon(1800);
  const onWheel = () => {
    pause();
    resumeSoon(1500);
  };

  const group = (hidden) => (
    <ul className="marquee-group" aria-hidden={hidden || undefined}>
      {[...items, ...items].map((skill, i) => (
        <li key={`${skill.name}-${i}`}>
          <SkillTile skill={skill} lit={lit.has(skill.name)} onToggle={onToggle} hidden={hidden} />
        </li>
      ))}
    </ul>
  );

  return (
    <div
      ref={rowRef}
      className="marquee-row"
      onPointerEnter={onPointerEnter}
      onPointerLeave={onPointerLeave}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={endDrag}
      onPointerCancel={endDrag}
      onClickCapture={onClickCapture}
      onTouchStart={onTouchStart}
      onTouchEnd={onTouchEnd}
      onTouchCancel={onTouchEnd}
      onWheel={onWheel}
      onFocus={pause}
      onBlur={() => resumeSoon(800)}
    >
      <div className="marquee-track">
        {group(false)}
        {group(true)}
      </div>
    </div>
  );
}

export default function Skills() {
  const [lit, setLit] = useState(() => new Set());

  const toggle = (name) =>
    setLit((prev) => {
      const next = new Set(prev);
      next.has(name) ? next.delete(name) : next.add(name);
      return next;
    });

  return (
    <section className="skills-section">
      <div className="section-tag">Skills & Tools</div>
      <h2 className="section-title">
        Technologies <span className="highlight">I use</span>
      </h2>
      <p className="section-sub">
        From full‑stack development to design and networking — tools I use daily to build robust digital solutions.
      </p>

      <div className="skills-marquee">
        <MarqueeRow items={ROW_ONE} speed={42} lit={lit} onToggle={toggle} />
        <MarqueeRow items={ROW_TWO} speed={32} lit={lit} onToggle={toggle} />
      </div>

      <p className="skills-hint">Drag or swipe to scroll. Hover or touch to pause. Click a logo to see its colors.</p>
    </section>
  );
}
